#!/bin/sh
# spot-watch: a systemd timer runs this every 5 s as root (G3-08). It writes the notice once.
IMDS=${IMDS:-http://169.254.169.254}
OUT=${OUT:-/run/nova/preempt}
[ -e "$OUT" ] && exit 0
token=$(curl -s -X PUT "$IMDS/latest/api/token" -H "X-aws-ec2-metadata-token-ttl-seconds: 60")
notice=$(curl -s -f -H "X-aws-ec2-metadata-token: $token" "$IMDS/latest/meta-data/spot/instance-action") || exit 0
mkdir -p "$(dirname "$OUT")"
echo "$notice" > "$OUT"
